package xyz.shuncongci.leica

import org.junit.Assert.*
import org.junit.Test
import java.io.File
import java.io.IOException
import java.nio.file.Files
import java.util.concurrent.CancellationException
import xyz.shuncongci.leica.LegendaryMath.Frame

class HdrOutputBrightnessTest {
    private fun frame(w:Int=13,h:Int=9)=Frame(w,h,3,FloatArray(w*h*3){(it*17%10003)/313f})
    private fun collect(p:HdrPixels):Frame {
        val out=Frame(p.w,p.h,3,FloatArray(p.w*p.h*3));val row=FloatArray(p.w)
        for(c in 0..2)for(y in 0 until p.h){p.read(c,y,1,row,Cancel());row.copyInto(out.data,c*out.size+y*p.w)}
        return out
    }
    private fun bits(a:FloatArray,b:FloatArray){assertEquals(a.size,b.size);for(i in a.indices)assertEquals("bits $i",a[i].toRawBits(),b[i].toRawBits())}
    private fun expected(f:Frame)=FloatArray(f.data.size){f.data[it]*1.25f}
    private fun <T> work(body:(File)->T):T {val d=Files.createTempDirectory("hdr-brightness").toFile();try{return body(d)}finally{check(d.deleteRecursively())}}
    private fun sdr(w:Int,h:Int)=Planes(w,h).also{p->for(c in 0..2)for(i in 0 until p.size)p.plane(c)[i]=(40+(i*13+c*59)%200).toByte()}

    @Test fun declaredGainIsQuarterLinearIncrease(){assertEquals(1.25f,HdrOutputBrightness.GAIN,0f);assertTrue(HdrOutputBrightness.ID.contains("1.25"))}
    @Test fun onePixelAllChannelsAreScaled(){val f=Frame(1,1,3,floatArrayOf(0f,.5f,4f));bits(expected(f),collect(HdrOutputBrightness.apply(HdrPixels.of(f))).data)}
    @Test fun allRowsChannelsAndDimensionsArePreserved(){val f=frame();val p=HdrOutputBrightness.apply(HdrPixels.of(f));assertEquals(f.w,p.w);assertEquals(f.h,p.h);bits(expected(f),collect(p).data)}
    @Test fun originalFloatBitsAreUntouched(){val f=frame();val before=f.data.copyOf();collect(HdrOutputBrightness.apply(HdrPixels.of(f)));bits(before,f.data)}
    @Test fun channelRatiosDoNotIntroduceAColorCast(){val f=Frame(1,1,3,floatArrayOf(.5f,1f,2f));val a=collect(HdrOutputBrightness.apply(HdrPixels.of(f))).data;assertEquals(2f,a[1]/a[0],0f);assertEquals(2f,a[2]/a[1],0f)}
    @Test fun superWhiteIsNotClippedOrToneMapped(){val f=Frame(1,1,3,floatArrayOf(1f,16f,100f));bits(floatArrayOf(1.25f,20f,125f),collect(HdrOutputBrightness.apply(HdrPixels.of(f))).data)}
    @Test fun zeroAndNegativeZeroAreNotLifted(){val f=Frame(1,1,3,floatArrayOf(0f,-0f,0f));bits(f.data,collect(HdrOutputBrightness.apply(HdrPixels.of(f))).data)}
    @Test fun unusedScratchTailIsNotModified(){val f=frame();val a=FloatArray(f.w*3){-7f};HdrOutputBrightness.apply(HdrPixels.of(f)).read(2,3,2,a,Cancel());bits(expected(f).copyOfRange(2*f.size+3*f.w,2*f.size+5*f.w),a.copyOf(f.w*2));assertTrue(a.drop(f.w*2).all{it==-7f})}
    @Test fun repeatedReadsDoNotAccumulateGain(){val f=frame();val p=HdrOutputBrightness.apply(HdrPixels.of(f));repeat(4){bits(expected(f),collect(p).data)}}
    @Test fun repeatedWrappingDoesNotAccumulateGain(){val f=frame();val p=HdrOutputBrightness.apply(HdrPixels.of(f));assertSame(p,HdrOutputBrightness.apply(p));bits(expected(f),collect(HdrOutputBrightness.apply(p)).data)}
    @Test fun largeVirtualRasterNeedsOnlyRequestedRows(){var reads=0;val source=object:HdrPixels{override val w=4096;override val h=8192;override fun read(channel:Int,y:Int,rows:Int,values:FloatArray,cancel:Cancel){assertEquals(2,channel);assertEquals(4000,y);assertEquals(3,rows);reads++;values.fill(2f,0,w*rows)}};val a=FloatArray(4096*3);HdrOutputBrightness.apply(source).read(2,4000,3,a,Cancel());assertEquals(1,reads);assertTrue(a.all{it==2.5f})}
    @Test fun invalidReadRangesRemainRejected(){val p=HdrOutputBrightness.apply(HdrPixels.of(frame()));for(call in listOf<()->Unit>({p.read(3,0,1,FloatArray(13),Cancel())},{p.read(0,-1,1,FloatArray(13),Cancel())},{p.read(0,0,0,FloatArray(13),Cancel())},{p.read(0,8,2,FloatArray(26),Cancel())},{p.read(0,0,1,FloatArray(12),Cancel())})){assertThrows(IllegalArgumentException::class.java){call()}}}
    @Test fun cancellationBeforeReadDoesNotTouchSource(){var read=false;val p=object:HdrPixels{override val w=1;override val h=1;override fun read(channel:Int,y:Int,rows:Int,values:FloatArray,cancel:Cancel){read=true}};assertThrows(CancellationException::class.java){HdrOutputBrightness.apply(p).read(0,0,1,FloatArray(1),Cancel().apply{cancelled=true})};assertFalse(read)}
    @Test fun cancellationDuringSourceReadIsNotIgnored(){val p=object:HdrPixels{override val w=1;override val h=1;override fun read(channel:Int,y:Int,rows:Int,values:FloatArray,cancel:Cancel){values[0]=1f;cancel.cancelled=true}};assertThrows(CancellationException::class.java){HdrOutputBrightness.apply(p).read(0,0,1,FloatArray(1),Cancel())}}
    @Test fun realIoFailureIsNotAnHdrFallback(){val marker=IOException("synthetic disk failure");val p=object:HdrPixels{override val w=1;override val h=1;override fun read(channel:Int,y:Int,rows:Int,values:FloatArray,cancel:Cancel){throw marker}};val caught=assertThrows(IOException::class.java){HdrOutputBrightness.apply(p).read(0,0,1,FloatArray(1),Cancel())};assertSame(marker,caught);assertFalse(HdrAutoPolicy.canFallback(caught))}
    @Test fun overflowIsRejectedWithoutClippingOrSdrFallback(){val f=Frame(1,1,3,floatArrayOf(65504f,0f,0f));val error=assertThrows(ArithmeticException::class.java){collect(HdrOutputBrightness.apply(HdrPixels.of(f)))};assertFalse(HdrAutoPolicy.canFallback(error));assertEquals(65504f,f.data[0],0f)}
    @Test fun invalidSourceRadianceStillFails(){for(v in listOf(Float.NaN,Float.POSITIVE_INFINITY,-1f,65505f)){assertThrows(IllegalArgumentException::class.java){collect(HdrOutputBrightness.apply(HdrPixels.of(Frame(1,1,3,floatArrayOf(v,0f,0f)))))}}}
    @Test fun invalidDimensionsAreRejected(){val p=object:HdrPixels{override val w=0;override val h=1;override fun read(channel:Int,y:Int,rows:Int,values:FloatArray,cancel:Cancel){fail()}};assertThrows(IllegalArgumentException::class.java){HdrOutputBrightness.apply(p)}}
    @Test fun hdrRenderIdentityChangesButSdrIdentityDoesNot(){for(mode in HdrDevelopMode.entries){val old=mode.renderKey("same-source-and-parameters");assertEquals(old,HdrOutputBrightness.renderKey(old,false));assertNotEquals(old,HdrOutputBrightness.renderKey(old,true));assertEquals(HdrOutputBrightness.renderKey(old,true),HdrOutputBrightness.renderKey(old,true))}}
    @Test fun oldHdrCheckpointCannotBeMistakenForNewResult()=work{d->val s=EditSession(d);val f=File(d,"import").apply{writeText("original")};s.importSource(f);val old=HdrDevelopMode.HDR.renderKey("scene");s.beginRender(old);s.store.update(blobs=mapOf("render.hdr" to {it.writeText("unexposed old checkpoint")},"result" to {it.writeText("last complete")},"result-pair" to {it.writeText("last pair")},"result-jpeg" to {it.writeText("last jpeg")}));s.beginRender(HdrOutputBrightness.renderKey(old,true));assertNull(s.store.file("render.hdr"));assertEquals("original",s.source()!!.readText());assertEquals("last complete",s.store.file("result")!!.readText());assertEquals("last pair",s.store.file("result-pair")!!.readText());assertEquals("last jpeg",s.store.file("result-jpeg")!!.readText())}
    @Test fun resumedRawCheckpointRemainsRawAndIsExposedOnce()=work{d->val f=frame();val raw=File(d,"raw");HdrFloatFile.write(raw,HdrPixels.of(f),Cancel());val bytes=raw.readBytes();repeat(3){HdrFloatFile.open(raw).use{bits(expected(f),collect(HdrOutputBrightness.apply(it)).data)}};assertArrayEquals(bytes,raw.readBytes())}
    @Test fun finishedPairKeepsSdrExactAndRepeatedSavesDoNotBrightenAgain()=work{d->val f=frame();val base=sdr(f.w,f.h);val before=Array(3){base.plane(it).copyOf()};val first=File(d,"finished");HdrResultStore.write(first,base,HdrOutputBrightness.apply(HdrPixels.of(f)),Cancel());repeat(3){n->val (p,hdr)=HdrResultStore.readRows(first,f.w,f.h,Cancel());hdr.use{pixels->bits(expected(f),collect(pixels).data);val copy=File(d,"export-$n");HdrResultStore.write(copy,p,pixels,Cancel());assertArrayEquals(first.readBytes(),copy.readBytes())};for(c in 0..2){assertArrayEquals(before[c],p.plane(c));assertArrayEquals(before[c],base.plane(c))}}}
    @Test fun cropAndAreaResizeDoNotReapplyExposure()=work{d->val f=frame(24,18);val pair=File(d,"finished");HdrResultStore.write(pair,sdr(f.w,f.h),HdrOutputBrightness.apply(HdrPixels.of(f)),Cancel());val scaled=Frame(f.w,f.h,3,expected(f));HdrResultStore.readRows(pair,f.w,f.h,Cancel()).second.use{p->for(crop in listOf(CompositionGeometry.FULL,CompositionGeometry.Crop(.25,0.0,.75,1.0))){val box=CompositionGeometry.pixels(crop,f.w,f.h);val size=box.w/2 to box.h/2;bits(HdrMath.geometry(scaled,crop,size.first,size.second,Cancel()).data,collect(HdrPixelGeometry.crop(p,crop,size.first,size.second)).data)}}}
    @Test fun gainmapEncoderReceivesTheSameBrighterRadiance() {val f=frame(17,11);val base=sdr(f.w,f.h);val bright=Frame(f.w,f.h,3,expected(f));val expected=HdrMath.encode(base,bright,Cancel());val pixels=IntArray(base.size);val actual=HdrMath.encodePixelRows(HdrOutputBrightness.apply(HdrPixels.of(f)),Cancel(),{y,rows,out->base.toArgbRows(y,rows,out)},{y,rows,out->System.arraycopy(out,0,pixels,y*f.w,rows*f.w)});assertEquals(expected.minimum.toRawBits(),actual.minimum.toRawBits());assertEquals(expected.maximum.toRawBits(),actual.maximum.toRawBits());assertEquals(expected.display.toRawBits(),actual.display.toRawBits());assertArrayEquals(expected.pixels,pixels);HdrMath.accept(HdrMath.error(bright,HdrMath.reconstruct(base,actual.copy(pixels=pixels),Cancel())))}
    @Test fun naturalBokehOutputOnlyGetsScalarGainAfterRendering()=work{d->val p=sdr(35,27);val original=Array(3){p.plane(it).copyOf()};val depth=Frame(3,3,1,floatArrayOf(.1f,.3f,.6f,.2f,.4f,.7f,.3f,.6f,.9f));val sharp=frame(35,27);val out=File(d,"natural");val made=FourTileBokeh.renderNatural(p,depth,.4f,2.8f,Cancel(),d,sharp=HdrPixels.of(sharp),hdrTarget=out);val before=Array(3){made.plane(it).copyOf()};HdrFloatFile.open(out).use{raw->val rendered=collect(raw);bits(expected(rendered),collect(HdrOutputBrightness.apply(raw)).data);bits(rendered.data,collect(raw).data)};for(c in 0..2){assertArrayEquals(before[c],made.plane(c));assertArrayEquals(original[c],p.plane(c))}}
}
